// Keeps the Apps Script project in sync with its repository sources.
//
//   node scripts/sync-apps-script.mjs           write the generated files
//   node scripts/sync-apps-script.mjs --check   exit 1 if any generated file has drifted
//
// Generated files:
// - apps-script/ProductionScript.js: a byte-for-byte copy of parser/src/production-script.cjs.
// - apps-script/ProductionEstimator.js: a byte-for-byte copy of
//   production/src/production-estimator.cjs.
// - apps-script/GeneratedData.js: the expected course structure, plus the
//   versions and SHA-256 hashes of the parser and estimator cores, for the
//   generation manifest.

import { createHash } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

const PARSER_CORE = "parser/src/production-script.cjs";
const PARSER_PACKAGE = "parser/package.json";
const ESTIMATOR_CORE = "production/src/production-estimator.cjs";
const ESTIMATOR_PACKAGE = "production/package.json";
const EXPECTED_STRUCTURE = "course/fixtures/expected-structure.json";

const repoRoot = new URL("../", import.meta.url);

function readRepoFile(relativePath) {
  return readFileSync(new URL(relativePath, repoRoot), "utf8");
}

function sha256Hex(text) {
  return createHash("sha256").update(text, "utf8").digest("hex");
}

// Returns { "<repo-relative path>": "<exact file content>" } for every generated file.
export function buildGeneratedFiles(read) {
  const core = read(PARSER_CORE);
  const estimatorCore = read(ESTIMATOR_CORE);
  const data = {
    parserVersion: JSON.parse(read(PARSER_PACKAGE)).version,
    parserCoreSha256: sha256Hex(core),
    estimatorVersion: JSON.parse(read(ESTIMATOR_PACKAGE)).version,
    estimatorCoreSha256: sha256Hex(estimatorCore),
    expectedStructure: JSON.parse(read(EXPECTED_STRUCTURE)),
  };
  const generatedData =
    `// GENERATED by scripts/sync-apps-script.mjs from ${EXPECTED_STRUCTURE},\n` +
    `// ${PARSER_PACKAGE}, ${PARSER_CORE},\n` +
    `// ${ESTIMATOR_PACKAGE}, and ${ESTIMATOR_CORE}. Don't edit by hand.\n` +
    `var GeneratedData = ${JSON.stringify(data, null, 2)};\n`;

  return {
    "apps-script/GeneratedData.js": generatedData,
    "apps-script/ProductionEstimator.js": estimatorCore,
    "apps-script/ProductionScript.js": core,
  };
}

// Compares generated content with what's on disk. Returns [{ path, reason }].
export function findDrift(expectedFiles, read) {
  const drift = [];
  for (const path of Object.keys(expectedFiles).sort()) {
    let actual;
    try {
      actual = read(path);
    } catch (error) {
      if (error.code === "ENOENT") {
        drift.push({ path, reason: "missing" });
        continue;
      }
      throw error;
    }
    if (actual !== expectedFiles[path]) {
      drift.push({ path, reason: "differs" });
    }
  }
  return drift;
}

function main(args) {
  const files = buildGeneratedFiles(readRepoFile);

  if (args.includes("--check")) {
    const drift = findDrift(files, readRepoFile);
    if (drift.length > 0) {
      for (const { path, reason } of drift) {
        console.error(`${path}: ${reason}`);
      }
      console.error("Apps Script files are out of date. Run: node scripts/sync-apps-script.mjs");
      return 1;
    }
    console.log("Apps Script files match their sources.");
    return 0;
  }

  for (const [path, content] of Object.entries(files)) {
    writeFileSync(new URL(path, repoRoot), content, "utf8");
    console.log(`wrote ${path}`);
  }
  return 0;
}

if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = main(process.argv.slice(2));
}
